(function injectBackground() {
  function doInject() {
    var el = document.getElementById('pxBgSvg');
    if (el) { el.innerHTML = BG_SVG_CONTENT; return true; }
    return false;
  }
  if (!doInject()) {
    document.addEventListener('DOMContentLoaded', doInject);
  }
})();

